from pathlib import Path
import json, re

path=Path('prefabricated-construction.html')
source=path.read_text()
sanitized=Path('.editorial-prefab/before-sanitized.html').read_text()
body=sanitized.split('<div class="article-body">',1)[1].split('<footer class="article-footer">',1)[0]
blocks=list(re.finditer(r'<(h[1-6]|p|li)\b[^>]*>(.*?)</\1>',body,re.S))
edits=[]

def fragment(old,new,reason):
    assert old!=new
    assert source.count(old)==1, (reason, source.count(old),old[:100])
    edits.append({'old':old,'new':new,'reason':reason})

def block(i,new,reason):
    fragment(blocks[i][0],new,reason)

abstract=[
'The Middle East’s conventional construction projects routinely face delays, cost inflation, labor shortages, design changes, and harsh weather. This paper proposes two complementary prefabrication systems for the UAE and wider region: Precast Concrete (PC) and Modular Integrated “BOX” technologies. Each serves different program goals and time horizons.',
'PC uses factory-cast structural elements for rapid assembly under familiar building codes, with century-scale durability. It suits permanent housing and large developments with repeated designs. BOX delivers fully finished volumetric units with structure, mechanical, electrical and plumbing (MEP) systems, and interiors installed in the factory. These units support plug-and-play installation, minimal site exposure, and relocation. They suit student and staff housing, youth apartments, micro-villas/ADUs, and rapid deployments.',
'Our case templates show shorter construction times: &lt;24‑hour unit installs for BOX and ~2–3 weeks for PC dwellings. Both systems reduce onsite labor and weather risk, stabilize costs through industrialized manufacturing, and improve quality through factory quality assurance. High thermal performance, strong fire and seismic performance, and standardized interfaces produce measurable ESG gains and improve long-term maintainability.',
'Governments can use BOX for urgent, mobile needs and PC for permanent neighborhoods that can expand. Aligning procurement, permitting, and design with these methods lets governments deliver habitable space faster, more safely, and at reliable quality. They retain flexibility for future public priorities.'
]
block(23,''.join('<p class="c32"><span class="c31 c11 c2">'+p+'</span></p>' for p in abstract),'Separate the abstract by topic; retain every mechanism, use, duration and consequence; remove metaphor and rhetorical negation.')
