for e in edits:
    source=source.replace(e['old'],e['new'],1)
path.write_text(source)
Path('.editorial-prefab/replacements.json').write_text(json.dumps(edits,ensure_ascii=False,indent=2)+'\n')
print(f'Applied {len(edits)} exact prose replacements; saved compact old/new handoff.')
